exercises.solution:
using System;

public class Program
{
    public static void Main()
    {
        Console.WriteLine(EhPrimo(7));
        Console.WriteLine(EhPrimo(10));
    }

    static bool EhPrimo(int n)
    {
        if (n < 2) return false;
        for (int i = 2; i * i <= n; i++)
            if (n % i == 0) return false;
        return true;
    }
}

