using System;

public class Program
{
    public static void Main()
    {
        var p = DividirParcelas(100.00m, 3);
        Console.WriteLine($"{p[0]:N2} + {p[1]:N2} + {p[2]:N2} = {p[0]+p[1]+p[2]:N2}");
    }

    static decimal[] DividirParcelas(decimal total, int n)
    {
        decimal valorBase = Math.Floor((total / n) * 100m) / 100m;
        decimal resto = total - (valorBase * n);
        var res = new decimal[n];
        for (int i = 0; i < n; i++)
        {
            res[i] = valorBase + (resto > 0 ? 0.01m : 0m);
            if (resto > 0) resto -= 0.01m;
        }
        return res;
    }
}

