    {
        IRepositorio<string> repo = new RepositorioMemoria<string>();
        var servico = new ServicoCadastro(repo);
        servico.Cadastrar("CSharp");
        servico.Cadastrar("DotNet");
        Console.WriteLine(servico.ObterQuantidade());
