using System;
using System.Collections.Generic;

public class Program
{
    public static void Main()
    {
        var numeros = new[] { 1, 2, 3, 4, 5, 6 };
        var pares = Filtrar(numeros, n => n % 2 == 0);
        Console.WriteLine(string.Join(", ", pares));
    }

    public static IEnumerable<T> Filtrar<T>(IEnumerable<T> fonte, Func<T, bool> predicado)
    {
        var res = new List<T>();
        foreach (var item in fonte)
            if (predicado(item)) res.Add(item);
        return res;
    }
}

