using System;
using System.Collections.Generic;
using System.Linq;

public class Program
{
    public static void Main()
    {
        var palavras = new[] { "sol", "lua", "mar", "casa", "bola", "estrela" };
        foreach (var item in ContarPalavrasPorTamanho(palavras))
            Console.WriteLine(item);
    }

    static IEnumerable<string> ContarPalavrasPorTamanho(string[] palavras) =>
        palavras
            .GroupBy(p => p.Length)
            .OrderBy(g => g.Key)
            .Select(g => $"{g.Key}: {g.Count()}");
}

