using System;
using System.Linq;

public class Program
{
    public static void Main()
    {
        var precos = new[] { 100m, 200m, 300m };
        var total = CalcularTotalComDesconto(precos, 0.10m);
        Console.WriteLine($"{total:F0}");
    }

    static decimal CalcularTotalComDesconto(decimal[] itens, decimal taxaDesconto) =>
        itens.Aggregate(0m, (acc, item) => acc + (item * (1m - taxaDesconto)));
}

