using System;
using System.Collections.Generic;
using System.Linq;

public class Program
{
    public static void Main()
    {
        var nums = new[] { 15, 3, 99, 42, 8, 77, 2 };
        var top3 = ObterTopN(nums, 3);
        Console.WriteLine(string.Join(", ", top3));
    }

    static IEnumerable<int> ObterTopN(int[] numeros, int n) =>
        numeros.OrderByDescending(x => x).Take(n);
}

