using System;
using System.Collections.Generic;

public class Program
{
    public static void Main()
    {
        var seq = GerarSequencia(10, 5, 4);
        Console.WriteLine(string.Join(" -> ", seq));
    }

    static IEnumerable<int> GerarSequencia(int inicio, int passo, int quantidade)
    {
        for (int i = 0; i < quantidade; i++)
            yield return inicio + (i * passo);
    }
}
